1	"use client";
2	
3	/**
4	 * Player-inventory editor for the free Minecraft Players tab.
5	 *
6	 * READ THIS BEFORE CHANGING THE COPY: vanilla RCON has no "read a player's
7	 * inventory" command — the only primitive is a write-only
8	 * `/item replace entity <player> <slot> with <item>[<count>]`. This UI is
9	 * deliberately NOT a live view of what's in someone's inventory; it's a
10	 * "set this slot to become X" tool. Every slot control below starts blank/
11	 * unselected on every render — it never claims to reflect current contents.
12	 */
13	import { useEffect, useMemo, useState, useTransition } from "react";
14	import { getFreeMinecraftPlayers } from "@/lib/actions-free-minecraft";
15	import { applyPlayerInventoryEdit, type ApplyInventoryEditState } from "@/lib/actions-freemc-inventory";
16	import { MINECRAFT_ITEMS, type MinecraftItem } from "@/lib/minecraft-items";
17	import { ARMOR_SLOTS, HAND_SLOTS, HOTBAR_SLOTS, MAIN_INVENTORY_SLOTS, type SlotDef } from "@/lib/minecraft-slots";
18	
19	type PendingEdit = { itemId: string; count: number };
20	
21	const CLEAR_ID = "minecraft:air";
22	
23	export function InventoryEditor({ running }: { running: boolean }) {
24	  const [players, setPlayers] = useState<{ name: string }[] | null>(null);
25	  const [playersError, setPlayersError] = useState<string | null>(null);
26	  const [player, setPlayer] = useState<string>("");
27	  const [edits, setEdits] = useState<Record<string, PendingEdit>>({});
28	  const [result, setResult] = useState<ApplyInventoryEditState | null>(null);
29	  const [pending, startTransition] = useTransition();
30	  const [refreshing, startRefresh] = useTransition();
31	
32	  function refreshPlayers() {
33	    startRefresh(async () => {
34	      const res = await getFreeMinecraftPlayers();
35	      if (res.ok) {
36	        setPlayers(res.players);
37	        setPlayersError(null);
38	        if (!res.players.some((p) => p.name === player)) setPlayer(res.players[0]?.name ?? "");
39	      } else {
40	        setPlayersError(res.error);
41	        setPlayers(null);
42	      }
43	    });
44	  }
45	  useEffect(() => {
46	    if (running) refreshPlayers();
47	    // eslint-disable-next-line react-hooks/exhaustive-deps
48	  }, [running]);
49	
50	  function setSlot(slot: string, next: Partial<PendingEdit>) {
51	    setEdits((prev) => {
52	      const current = prev[slot] ?? { itemId: "", count: 1 };
53	      const merged = { ...current, ...next };
54	      // Dropping back to "no item chosen" removes the pending edit entirely
55	      // rather than submitting a no-op.
56	      if (!merged.itemId) {
57	        const { [slot]: _drop, ...rest } = prev;
58	        return rest;
59	      }
60	      return { ...prev, [slot]: merged };
61	    });
62	  }
63	
64	  const pendingCount = Object.keys(edits).length;
65	
66	  function submit() {
67	    if (!player || pendingCount === 0) return;
68	    const payload = Object.entries(edits).map(([slot, e]) => ({
69	      slot,
70	      itemId: e.itemId,
71	      count: e.itemId === CLEAR_ID ? 1 : e.count,
72	    }));
73	    const fd = new FormData();
74	    fd.set("player", player);
75	    fd.set("edits", JSON.stringify(payload));
76	    startTransition(async () => {
77	      const res = await applyPlayerInventoryEdit({}, fd);
78	      setResult(res);
79	      if (!res.error) setEdits({});
80	    });
81	  }
82	
83	  return (
84	    <div className="card space-y-5">
85	      <div>
86	        <h3 className="font-semibold text-[var(--fg)]">Give items</h3>
87	        <p className="mt-1 text-sm text-slate-400">
88	          Minecraft doesn&apos;t let us read what&apos;s currently in a player&apos;s inventory over RCON — this tool only
89	          <span className="text-slate-300"> sets</span> slots to whatever you pick below. It doesn&apos;t show current
90	          contents, and picking a slot below will overwrite whatever&apos;s already there.
91	        </p>
92	      </div>
93	
94	      {!running ? (
95	        <p className="text-sm text-slate-500">Server is asleep — nobody&apos;s connected. Wake it up to edit inventories.</p>
96	      ) : (
97	        <>
98	          <div className="flex flex-wrap items-end gap-3">
99	            <div>
100	              <label className="label mb-1 block">Player</label>
101	              <select className="input" value={player} onChange={(e) => setPlayer(e.target.value)} disabled={!players?.length}>
102	                {!players?.length && <option value="">No one online</option>}
103	                {players?.map((p) => (
104	                  <option key={p.name} value={p.name}>
105	                    {p.name}
106	                  </option>
107	                ))}
108	              </select>
109	            </div>
110	            <button type="button" className="btn-ghost text-xs" onClick={refreshPlayers} disabled={refreshing}>
111	              {refreshing ? "Refreshing…" : "Refresh players"}
112	            </button>
113	            {playersError && <p className="text-sm text-red-400">{playersError}</p>}
114	          </div>
115	
116	          {player && (
117	            <>
118	              <SlotGroup title="Armor & hands" slots={[...ARMOR_SLOTS, ...HAND_SLOTS]} edits={edits} setSlot={setSlot} cols="grid-cols-2 sm:grid-cols-3" />
119	              <SlotGroup title="Hotbar" slots={HOTBAR_SLOTS} edits={edits} setSlot={setSlot} cols="grid-cols-3 sm:grid-cols-5" />
120	              <SlotGroup title="Main inventory" slots={MAIN_INVENTORY_SLOTS} edits={edits} setSlot={setSlot} cols="grid-cols-3 sm:grid-cols-5" />
121	
122	              {result?.error && (
123	                <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{result.error}</div>
124	              )}
125	              {result?.results && (
126	                <div className="rounded-lg border border-white/[0.08] bg-black/20 p-3 text-xs">
127	                  {result.results.map((r) => (
128	                    <p key={r.slot} className={r.ok ? "text-emerald-300" : "text-red-400"}>
129	                      {r.slot}: {r.ok ? "applied" : r.message}
130	                    </p>
131	                  ))}
132	                </div>
133	              )}
134	
135	              <div className="flex items-center justify-between border-t border-white/[0.06] pt-4">
136	                <p className="text-xs text-slate-500">
137	                  {pendingCount === 0 ? "Pick items for one or more slots above." : `${pendingCount} slot${pendingCount === 1 ? "" : "s"} queued to change.`}
138	                </p>
139	                <button type="button" className="btn-primary text-sm" onClick={submit} disabled={pending || pendingCount === 0}>
140	                  {pending ? "Applying…" : "Apply to " + player}
141	                </button>
142	              </div>
143	            </>
144	          )}
145	        </>
146	      )}
147	    </div>
148	  );
149	}
150	
151	function SlotGroup({
152	  title,
153	  slots,
154	  edits,
155	  setSlot,
156	  cols,
157	}: {
158	  title: string;
159	  slots: SlotDef[];
160	  edits: Record<string, PendingEdit>;
161	  setSlot: (slot: string, next: Partial<PendingEdit>) => void;
162	  cols: string;
163	}) {
164	  return (
165	    <div>
166	      <h4 className="text-xs font-semibold uppercase tracking-wide text-slate-500">{title}</h4>
167	      <div className={`mt-2 grid gap-2 ${cols}`}>
168	        {slots.map((s) => (
169	          <SlotCell key={s.slot} slotDef={s} value={edits[s.slot]} onChange={(next) => setSlot(s.slot, next)} />
170	        ))}
171	      </div>
172	    </div>
173	  );
174	}
175	
176	function SlotCell({
177	  slotDef,
178	  value,
179	  onChange,
180	}: {
181	  slotDef: SlotDef;
182	  value: PendingEdit | undefined;
183	  onChange: (next: Partial<PendingEdit>) => void;
184	}) {
185	  const active = !!value?.itemId;
186	  return (
187	    <div
188	      className={`rounded-lg border px-2 py-2 text-xs transition-colors ${
189	        active ? "border-brand-400/50 bg-brand-500/10" : "border-white/[0.08]"
190	      }`}
191	    >
192	      <p className="mb-1 truncate text-slate-400" title={slotDef.label}>
193	        {slotDef.label}
194	      </p>
195	      <ItemPicker value={value?.itemId ?? ""} onSelect={(itemId) => onChange({ itemId })} />
196	      {active && value?.itemId !== CLEAR_ID && (
197	        <input
198	          type="number"
199	          className="input mt-1 w-full px-1.5 py-1 text-xs"
200	          min={1}
201	          max={64}
202	          value={value?.count ?? 1}
203	          onChange={(e) => onChange({ count: Math.max(1, Math.min(64, Number(e.target.value) || 1)) })}
204	        />
205	      )}
206	    </div>
207	  );
208	}
209	
210	/** Filtered combobox over the ~400-entry catalog — a plain <select> with
211	 *  every entry would be unusable to scroll, so this is a text filter over a
212	 *  <datalist>-free custom dropdown (keeps it dependency-free). */
213	function ItemPicker({ value, onSelect }: { value: string; onSelect: (itemId: string) => void }) {
214	  const [query, setQuery] = useState("");
215	  const [open, setOpen] = useState(false);
216	  const selected = MINECRAFT_ITEMS.find((it) => it.id === value);
217	
218	  const matches = useMemo(() => {
219	    if (!query.trim()) return MINECRAFT_ITEMS.slice(0, 40);
220	    const q = query.trim().toLowerCase();
221	    return MINECRAFT_ITEMS.filter((it) => it.label.toLowerCase().includes(q) || it.id.includes(q)).slice(0, 40);
222	  }, [query]);
223	
224	  return (
225	    <div className="relative">
226	      <input
227	        className="input w-full px-1.5 py-1 text-xs"
228	        placeholder={selected ? selected.label : "Search item…"}
229	        value={query}
230	        onFocus={() => setOpen(true)}
231	        onChange={(e) => {
232	          setQuery(e.target.value);
233	          setOpen(true);
234	        }}
235	        onBlur={() => setTimeout(() => setOpen(false), 150)}
236	      />
237	      {selected && !open && <p className="mt-0.5 truncate text-[11px] text-brand-300">{selected.label}</p>}
238	      {open && (
239	        <div className="absolute z-10 mt-1 max-h-56 w-56 overflow-y-auto rounded-lg border border-white/10 bg-navy-900 shadow-xl">
240	          <button
241	            type="button"
242	            className="block w-full px-2 py-1.5 text-left text-[11px] text-slate-500 hover:bg-white/5"
243	            onMouseDown={(e) => {
244	              e.preventDefault();
245	              onSelect("");
246	              setQuery("");
247	              setOpen(false);
248	            }}
249	          >
250	            Clear selection
251	          </button>
252	          {matches.map((it: MinecraftItem) => (
253	            <button
254	              key={it.id}
255	              type="button"
256	              className="block w-full px-2 py-1.5 text-left text-[11px] hover:bg-white/5"
257	              onMouseDown={(e) => {
258	                e.preventDefault();
259	                onSelect(it.id);
260	                setQuery("");
261	                setOpen(false);
262	              }}
263	            >
264	              <span className="text-[var(--fg)]">{it.label}</span>
265	              <span className="ml-1 text-slate-500">{it.category}</span>
266	            </button>
267	          ))}
268	          {matches.length === 0 && <p className="px-2 py-1.5 text-[11px] text-slate-500">No matches.</p>}
269	        </div>
270	      )}
271	    </div>
272	  );
273	}
