1	"use server";
2	
3	/**
4	 * Player-inventory editor for free-tier Minecraft servers (Players tab).
5	 *
6	 * IMPORTANT LIMITATION, by design: vanilla RCON has no "read a player's
7	 * current inventory" command. The only inventory primitive available is the
8	 * WRITE-only `/item replace entity <player> <slot> with <item>[<count>]`
9	 * (stable since 1.19, confirmed current for 26.x — see lib/minecraft-slots.ts
10	 * for the live-verified slot vocabulary and how it was tested). There is
11	 * therefore no way to show what a slot currently holds — this is a "set this
12	 * slot to become X" tool, not a live view+edit of contents. The client
13	 * component is explicit about that; this file never claims to read
14	 * inventory state.
15	 *
16	 * `with air` (no count) clears a slot, equivalent to deleting whatever was
17	 * there — used here whenever the caller picks the "(Empty / clear slot)"
18	 * catalog entry. Also live-verified: it parses cleanly through to entity
19	 * resolution rather than failing as a bad command.
20	 *
21	 * Every value that reaches the RCON command string is validated against a
22	 * fixed allowlist first (slot names, item ids, integer count range) — same
23	 * "reject, never sanitize" posture as lib/ssh-exec.ts and validateRconCommand
24	 * in lib/game-control.ts. The item id and slot name are NEVER taken as free
25	 * text; both must exactly match a known-good value or the whole submission
26	 * is rejected before anything touches the SSH connection. The player name
27	 * that actually reaches the command string is likewise never the caller's
28	 * raw input — see the PLAYER_NAME_RE check below plus the online-list
29	 * re-match inside applyPlayerInventoryEdit.
30	 */
31	import { db } from "./db";
32	import { requireUser } from "./auth";
33	import { checkRateLimit } from "./rate-limit";
34	import { withServerSsh } from "./ssh-exec";
35	import type { SftpServer } from "./sftp";
36	import { sendRcon, getFreeServerPlayers } from "./free-minecraft-control";
37	import { isKnownMinecraftItemId } from "./minecraft-items";
38	import { isValidSlotName, ALL_SLOTS } from "./minecraft-slots";
39	
40	/** Same lookup pattern as freemcHost() in lib/actions-free-minecraft.ts —
41	 *  that helper isn't exported, so it's reproduced here rather than reaching
42	 *  into another module's internals. */
43	async function freemcHost(): Promise<SftpServer> {
44	  const host = await db.server.findFirst({
45	    where: { hostname: "freemc-host" },
46	    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
47	  });
48	  if (!host) throw new Error("Free Minecraft host is not provisioned.");
49	  return host;
50	}
51	
52	/** Vanilla Minecraft username charset (offline-mode names, which is what
53	 *  this fleet runs with ONLINE_MODE=FALSE, follow the same rules). */
54	const PLAYER_NAME_RE = /^[A-Za-z0-9_]{1,16}$/;
55	
56	export type InventoryEditRequest = { slot: string; itemId: string; count: number };
57	export type InventoryEditResult = { slot: string; ok: boolean; message: string };
58	export type ApplyInventoryEditState = {
59	  error?: string;
60	  results?: InventoryEditResult[];
61	};
62	
63	/** Parse+validate the raw JSON payload the client posts. Never trusts shape
64	 *  or content — every field is re-checked against its allowlist here. */
65	function parseEdits(raw: string): { ok: true; edits: InventoryEditRequest[] } | { ok: false; error: string } {
66	  let parsed: unknown;
67	  try {
68	    parsed = JSON.parse(raw);
69	  } catch {
70	    return { ok: false, error: "Malformed submission." };
71	  }
72	  if (!Array.isArray(parsed) || parsed.length === 0) {
73	    return { ok: false, error: "Pick at least one slot to change." };
74	  }
75	  if (parsed.length > ALL_SLOTS.length) {
76	    return { ok: false, error: "Too many slot changes in one submission." };
77	  }
78	
79	  const edits: InventoryEditRequest[] = [];
80	  for (const raw of parsed) {
81	    if (typeof raw !== "object" || raw === null) return { ok: false, error: "Malformed slot entry." };
82	    const slot = String((raw as Record<string, unknown>).slot ?? "");
83	    const itemId = String((raw as Record<string, unknown>).itemId ?? "");
84	    const countRaw = (raw as Record<string, unknown>).count;
85	    const count = typeof countRaw === "number" ? countRaw : Number(countRaw);
86	
87	    if (!isValidSlotName(slot)) return { ok: false, error: `Unknown slot: ${slot}` };
88	    if (!isKnownMinecraftItemId(itemId)) return { ok: false, error: `Unknown item: ${itemId}` };
89	    if (!Number.isInteger(count) || count < 1 || count > 64) {
90	      return { ok: false, error: `Count for ${slot} must be a whole number from 1 to 64.` };
91	    }
92	    edits.push({ slot, itemId, count });
93	  }
94	  return { ok: true, edits };
95	}
96	
97	/**
98	 * Applies one or more "set this slot to X" edits to a currently-online
99	 * player on the caller's own free server. Refuses outright if the target
100	 * isn't online right now — there's no server-side concept of "queue it for
101	 * next login" here, `/item replace entity` only affects an entity that
102	 * currently exists in the world.
103	 */
104	export async function applyPlayerInventoryEdit(
105	  _prev: ApplyInventoryEditState,
106	  formData: FormData,
107	): Promise<ApplyInventoryEditState> {
108	  const user = await requireUser();
109	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
110	  if (!row) return { error: "You don't have a free server." };
111	
112	  // One rate-limit hit per SUBMISSION (which may fire several RCON calls
113	  // server-side) — mirrors sendFreeMinecraftCommand's console rate limit,
114	  // just a bit tighter since a single submit can be multiple live commands.
115	  const rl = checkRateLimit(`freemc:inventory:${user.id}`, { max: 12, windowMs: 60_000 });
116	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
117	
118	  const requestedPlayer = String(formData.get("player") ?? "").trim();
119	  if (!PLAYER_NAME_RE.test(requestedPlayer)) return { error: "Pick a valid player." };
120	
121	  const parsed = parseEdits(String(formData.get("edits") ?? ""));
122	  if (!parsed.ok) return { error: parsed.error };
123	
124	  try {
125	    const host = await freemcHost();
126	    return await withServerSsh(host, async (conn) => {
127	      // Re-check online status server-side at submit time (the client's list
128	      // is just a UI convenience, not something we trust) and pull the
129	      // EXACT case the server currently knows the player by — Minecraft
130	      // target selectors match the live username, so use it, not whatever
131	      // case the caller happened to type or a stale dropdown value had.
132	      const online = await getFreeServerPlayers(conn, row.containerName, user.id);
133	      if (!online.ok) return { error: online.error || "Couldn't reach your server — is it asleep?" };
134	      const match = online.players.find((p) => p.name.toLowerCase() === requestedPlayer.toLowerCase());
135	      if (!match) return { error: `${requestedPlayer} isn't online right now — they need to be connected to receive items.` };
136	      // Belt-and-suspenders: the name came back from our own `list` RCON
137	      // parse, but re-run it through the same charset check before it's
138	      // interpolated into a command string rather than trusting any upstream
139	      // parse implicitly.
140	      if (!PLAYER_NAME_RE.test(match.name)) return { error: "Couldn't validate the online player's name — please try again." };
141	
142	      const results: InventoryEditResult[] = [];
143	      for (const edit of parsed.edits) {
144	        const clearing = edit.itemId === "minecraft:air";
145	        const command = clearing
146	          ? `item replace entity ${match.name} ${edit.slot} with minecraft:air`
147	          : `item replace entity ${match.name} ${edit.slot} with ${edit.itemId} ${edit.count}`;
148	        const r = await sendRcon(conn, row.containerName, user.id, command);
149	        results.push({
150	          slot: edit.slot,
151	          ok: r.ok,
152	          message: r.ok ? r.response || "Applied." : r.error,
153	        });
154	      }
155	      return { results };
156	    });
157	  } catch (e) {
158	    console.error("[free-minecraft] inventory edit failed:", e);
159	    return { error: "Couldn't reach your server — is it asleep? Connect first to wake it up." };
160	  }
161	}
