"use client";

import { useActionState, useEffect, useState, useTransition } from "react";
import {
  deleteFreeMinecraftServer,
  startFreeMinecraftServer,
  stopFreeMinecraftServer,
  restartFreeMinecraftServer,
  renameFreeMinecraftServer,
  changeFreeMinecraftSubdomain,
  sendFreeMinecraftCommand,
  getFreeMinecraftPlayers,
  applyFreeMinecraftSettings,
  applyFreeMinecraftPreset,
} from "@/lib/actions-free-minecraft";
import { PublicListingCard } from "./PublicListingCard";
import { InventoryEditor } from "./InventoryEditor";
import { ModsTab } from "./ModsTab";
import { RolesTab } from "./RolesTab";

type Server = {
  id: string;
  subdomain: string;
  name: string | null;
  preset: string;
  running: boolean;
  players: { online: number; max: number } | null;
  isPublic: boolean;
  publicTagline: string | null;
  publicDescription: string | null;
  extraMods: string[];
};

type Field = {
  key: string;
  label: string;
  group: string;
  type: "enum" | "bool" | "int" | "string";
  default: string | number | boolean;
  options?: { value: string; label: string }[];
  min?: number;
  max?: number;
  phase: "deploy" | "live";
  help?: string;
};

type Preset = { label: string; description: string; kind: "properties" | "plugins"; properties: Record<string, string>; setupNote?: string };

const TABS = [
  { key: "overview", label: "Overview" },
  { key: "console", label: "Console" },
  { key: "players", label: "Players" },
  { key: "mods", label: "Mods" },
  { key: "roles", label: "Roles" },
  { key: "settings", label: "Settings" },
  { key: "manage", label: "Manage" },
] as const;
type TabKey = (typeof TABS)[number]["key"];

export function FreeMcDashboard({
  server,
  domain,
  schemaFields,
  properties,
  presets,
}: {
  server: Server;
  domain: string;
  schemaFields: Field[];
  properties: Record<string, string>;
  presets: Record<string, Preset>;
}) {
  const [tab, setTab] = useState<TabKey>("overview");
  const address = `${server.subdomain}.${domain}`;

  return (
    <div className="space-y-6">
      <div className="card flex flex-wrap items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-2.5">

