/**
 * Visual identity for the ~400-entry catalog in lib/minecraft-items.ts.
 *
 * ICON SOURCING NOTE (read before touching this file): Minecraft's actual
 * item textures are Mojang-copyrighted game assets. The Minecraft Wiki's own
 * item renders (the standard "legit" source the community usually reaches
 * for) are published under CC BY-NC-SA 3.0 — the NC (NonCommercial) clause
 * makes them unusable here, since Nxeon is a commercial hosting product, not
 * a fan wiki. The other candidates investigated (e.g. github.com/Krutoy242/
 * mc-icons, github.com/undrfined/mc-icons) turned out to be raw textures
 * extracted straight from the game client via mods, republished with no
 * license file at all — exactly the "unlicensed texture-pack mirror" this
 * was supposed to avoid. No properly-licensed, downloadable real-texture
 * source turned up in reasonable time, so this ships the documented
 * fallback instead: a small set of hand-authored, original line-art SVG
 * glyphs (not derived from any Minecraft asset), assigned per item by
 * *kind* (pickaxe/sword/helmet/…) and tinted by *material* (wood/iron/gold/
 * diamond/…), with a category-level glyph for everything else (food →
 * apple, ore → chunk, block → cube, etc.) — same spirit as a "sword icon
 * for weapons, generic block icon for blocks." Nothing here is a Minecraft
 * texture, screenshot, or derivative of one.
 */
import { MINECRAFT_ITEMS_BY_ID, type MinecraftItem } from "@/lib/minecraft-items";

type GlyphKey =
  | "pickaxe"
  | "axe"
  | "shovel"
  | "hoe"
  | "sword"
  | "bow"
  | "crossbow"
  | "trident"
  | "shield"
  | "arrow"
  | "mace"
  | "helmet"
  | "chestplate"
  | "leggings"
  | "boots"
  | "elytra"
  | "turtleShell"
  | "apple"
  | "gem"
  | "cube"
  | "oreChunk"
  | "redstoneDust"
  | "wheat"
  | "potion"
  | "wrench"
  | "skull"
  | "egg"
  | "air"
  | "unknown";

const KIND_GLYPHS: Record<string, GlyphKey> = {
  pickaxe: "pickaxe",
  axe: "axe",
  shovel: "shovel",
  hoe: "hoe",
  sword: "sword",
  helmet: "helmet",
  chestplate: "chestplate",
  leggings: "leggings",
  boots: "boots",
};

const SPECIAL_GLYPH_BY_ID: Record<string, GlyphKey> = {
  "minecraft:bow": "bow",
  "minecraft:crossbow": "crossbow",
  "minecraft:trident": "trident",
  "minecraft:shield": "shield",
  "minecraft:arrow": "arrow",
  "minecraft:spectral_arrow": "arrow",
  "minecraft:mace": "mace",
  "minecraft:elytra": "elytra",
  "minecraft:turtle_helmet": "turtleShell",
  "minecraft:air": "air",
};

const CATEGORY_GLYPH: Record<string, GlyphKey> = {
  Tools: "pickaxe",
  Weapons: "sword",
  Armor: "chestplate",
  Food: "apple",
  Valuables: "gem",
  Blocks: "cube",
  Ores: "oreChunk",
  Redstone: "redstoneDust",
  Farming: "wheat",
  Potions: "potion",
  Utility: "wrench",
  Heads: "skull",
  "Spawn Eggs": "egg",
};

/** Material tier -> tint color. Keys are matched against every underscore-
 *  separated segment of the item id (not just the first), so "raw_iron",
 *  "deepslate_iron_ore" and "iron_ingot" all pick up the iron tint even
 *  though "iron" isn't always the leading segment. */
const MATERIAL_COLOR: Record<string, string> = {
  wooden: "#b08b57",
  wood: "#b08b57",
  stone: "#9a9a9a",
  iron: "#d8dadd",
  golden: "#f0c750",
  gold: "#f0c750",
  diamond: "#5fe3e0",
  netherite: "#6a6470",
  leather: "#b3742f",
  chainmail: "#9aa0a6",
  copper: "#d08a5c",
  emerald: "#3fd67a",
  lapis: "#3f6fe0",
  coal: "#4a4a52",
  redstone: "#e0483f",
  amethyst: "#a877e6",
  quartz: "#e8e4db",
  prismarine: "#5fc4b8",
};

const DEFAULT_CATEGORY_COLOR: Record<string, string> = {
  Tools: "#c9c2ff",
  Weapons: "#e0483f",
  Armor: "#8a70fb",
  Food: "#8bc34a",
  Valuables: "#5fe3e0",
  Blocks: "#9a9a9a",
  Ores: "#c98a4b",
  Redstone: "#e0483f",
  Farming: "#7cb342",
  Potions: "#8a70fb",
  Utility: "#a89aff",
  Heads: "#c9c2ff",
  "Spawn Eggs": "#8bc34a",
};

function resolveGlyph(item: MinecraftItem): GlyphKey {
  const special = SPECIAL_GLYPH_BY_ID[item.id];
  if (special) return special;
  const bare = item.id.replace(/^minecraft:/, "");
  const segments = bare.split("_");
  const last = segments[segments.length - 1];
  const kind = KIND_GLYPHS[last];
  if (kind) return kind;
  return CATEGORY_GLYPH[item.category] ?? "unknown";
}

function resolveColor(item: MinecraftItem): string {
  const bare = item.id.replace(/^minecraft:/, "");
  const segments = bare.split("_");
  for (const seg of segments) {
    if (MATERIAL_COLOR[seg]) return MATERIAL_COLOR[seg];
  }
  return DEFAULT_CATEGORY_COLOR[item.category] ?? "#94a3b8";
}

/** Shared line-art stroke props for every glyph body. */
const STROKE = { fill: "none", stroke: "currentColor", strokeWidth: 1.6, strokeLinecap: "round" as const, strokeLinejoin: "round" as const };

function Glyph({ glyph }: { glyph: GlyphKey }) {
  switch (glyph) {
    case "pickaxe":
      return (
        <g {...STROKE}>
          <path d="M5 7c2-3 5-4.5 8-4.5S17 4 19 7" />
          <path d="M6 8.5 17.5 20" />
        </g>
      );
    case "axe":
      return (
        <g {...STROKE}>
          <path d="M8 4c4-1 8 1 8 5-4 1-7-.5-8-3.5Z" />
          <path d="M8.5 6.5 5 20" />
        </g>
      );
    case "shovel":
      return (
        <g {...STROKE}>
          <path d="M12 3v11" />
          <rect x="9" y="14" width="6" height="6" rx="1.5" />
        </g>
      );
    case "hoe":
      return (
        <g {...STROKE}>
          <path d="M6 20 17 6" />
          <path d="M14 4h5v4" />
        </g>
      );
    case "sword":
      return (
        <g {...STROKE}>
          <path d="M12 2v13" />
          <path d="M8 15h8" />
          <path d="M10.5 15v3l1.5 2 1.5-2v-3" />
        </g>
      );
    case "bow":
      return (
        <g {...STROKE}>
          <path d="M8 3c-3 3.5-3 13.5 0 18" />
          <path d="M8 3v18" />
          <path d="M8 11h9" />
        </g>
      );
    case "crossbow":
      return (
        <g {...STROKE}>
          <path d="M3 8c2-1 4-1 5 1M21 8c-2-1-4-1-5 1" />
          <path d="M4 7l16 1" />
          <path d="M12 5v14" />
        </g>
      );
    case "trident":
      return (
        <g {...STROKE}>
          <path d="M12 5v16" />
          <path d="M8 3v5M16 3v5M12 3v5" />
          <path d="M8 5h8" />
        </g>
      );
    case "shield":
      return (
        <g {...STROKE}>
          <path d="M12 3l7 2.5v5c0 5-3.5 8.5-7 10-3.5-1.5-7-5-7-10v-5Z" />
          <path d="M12 7v9" />
        </g>
      );
    case "arrow":
      return (
        <g {...STROKE}>
          <path d="M5 19 18 6" />
          <path d="M12 6h6v6" />
          <path d="M5 19l2-5M5 19l5-2" />
        </g>
      );
    case "mace":
      return (
        <g {...STROKE}>
          <path d="M12 11v10" />
          <path d="M8 5a4 4 0 0 1 8 0 4 4 0 0 1-8 0Z" />
          <path d="M6 3l1.5 2M18 3l-1.5 2M6 9l1.5-2M18 9l-1.5-2" />
        </g>
      );
    case "helmet":
      return (
        <g {...STROKE}>
          <path d="M5 14c0-5 3-9 7-9s7 4 7 9" />
          <path d="M5 14h14v2H5Z" />
        </g>
      );
    case "chestplate":
      return (
        <g {...STROKE}>
          <path d="M7 6c0-1.5 2-2.5 5-2.5S17 4.5 17 6v3c1.5.5 2 2 2 3.5V20H5v-7.5c0-1.5.5-3 2-3.5Z" />
          <path d="M9.5 5.5v15M14.5 5.5v15" />
        </g>
      );
    case "leggings":
      return (
        <g {...STROKE}>
          <path d="M7 3h10v9l-2 9h-2l-1-9-1 9H9L7 12Z" />
          <path d="M7 8h10" />
        </g>
      );
    case "boots":
      return (
        <g {...STROKE}>
          <path d="M9 3v9l-5 3v4h9v-4h4l-1-4h-3V3Z" />
        </g>
      );
    case "elytra":
      return (
        <g {...STROKE}>
          <path d="M12 4c-3 2-7 5-8 12 3-1 6-3 8-6 2 3 5 5 8 6-1-7-5-10-8-12Z" />
        </g>
      );
    case "turtleShell":
      return (
        <g {...STROKE}>
          <path d="M4 13c0-5 3.5-9 8-9s8 4 8 9-3.5 6-8 6-8-1-8-6Z" />
          <path d="M12 4v15M6 9l12 0M6 17l12 0" />
        </g>
      );
    case "apple":
      return (
        <g {...STROKE}>
          <path d="M12 9c-3-2-7 0-7 5s3 7 6 7c.7 0 1.3-.2 1-.2s.3.2 1 .2c3 0 6-2.5 6-7s-4-6-7-4Z" />
          <path d="M12 9V6M12 6c0-1.5 1-2 2-2" />
        </g>
      );
    case "gem":
      return (
        <g {...STROKE}>
          <path d="M6 9 12 3l6 6-6 12Z" />
          <path d="M6 9h12M9 9l3 12M15 9l-3 12" />
        </g>
      );
    case "cube":
      return (
        <g {...STROKE}>
          <path d="M12 3 20 7.5 12 12 4 7.5Z" />
          <path d="M4 7.5V16l8 4.5V12M20 7.5V16l-8 4.5" />
        </g>
      );
    case "oreChunk":
      return (
        <g {...STROKE}>
          <path d="M6 8 10 4h6l3 4-2 8-5 4-6-3Z" />
          <circle cx="11" cy="10" r="1" fill="currentColor" stroke="none" />
          <circle cx="15" cy="13" r="1" fill="currentColor" stroke="none" />
        </g>
      );
    case "redstoneDust":
      return (
        <g {...STROKE}>
          <path d="M4 15 9 9l3 3 3-5 5 5" />
          <circle cx="4" cy="15" r="1.3" fill="currentColor" stroke="none" />
          <circle cx="9" cy="9" r="1.3" fill="currentColor" stroke="none" />
          <circle cx="12" cy="12" r="1.3" fill="currentColor" stroke="none" />
          <circle cx="15" cy="7" r="1.3" fill="currentColor" stroke="none" />
          <circle cx="20" cy="12" r="1.3" fill="currentColor" stroke="none" />
        </g>
      );
    case "wheat":
      return (
        <g {...STROKE}>
          <path d="M8 21V7M12 21V4M16 21V7" />
          <path d="M8 9l-2-2M8 13l-2-2M12 6l-2-2M12 10l-2-2M16 9l2-2M16 13l2-2" />
        </g>
      );
    case "potion":
      return (
        <g {...STROKE}>
          <path d="M10 3h4v3l2 2v10a2 2 0 0 1-2 2h-4a2 2 0 0 1-2-2V8l2-2Z" />
          <path d="M8 14c1 1 2 1 4 1s3 0 4-1" />
        </g>
      );
    case "wrench":
      return (
        <g {...STROKE}>
          <path d="M15 5a4 4 0 0 0-5.3 4.6L4 15.3l2.7 2.7 5.7-5.7A4 4 0 0 0 19 8.4L16.4 11 13 7.6Z" />
        </g>
      );
    case "skull":
      return (
        <g {...STROKE}>
          <path d="M6 11c0-4 2.7-7 6-7s6 3 6 7c0 2.5-1 3.7-1.5 5H7.5c-.5-1.3-1.5-2.5-1.5-5Z" />
          <circle cx="9.5" cy="11" r="1" fill="currentColor" stroke="none" />
          <circle cx="14.5" cy="11" r="1" fill="currentColor" stroke="none" />
          <path d="M9 19h6M10 16v3M14 16v3" />
        </g>
      );
    case "egg":
      return (
        <g {...STROKE}>
          <path d="M12 21c-4 0-6-3.5-6-8 0-5 3-9.5 6-9.5s6 4.5 6 9.5c0 4.5-2 8-6 8Z" />
          <circle cx="10.5" cy="10" r="0.8" fill="currentColor" stroke="none" />
          <circle cx="13.5" cy="13" r="0.8" fill="currentColor" stroke="none" />
          <circle cx="11" cy="15" r="0.8" fill="currentColor" stroke="none" />
        </g>
      );
    case "air":
      return (
        <g {...STROKE} strokeDasharray="2.5 2.5">
          <rect x="4.5" y="4.5" width="15" height="15" rx="3" />
        </g>
      );
    case "unknown":
    default:
      return (
        <g {...STROKE}>
          <circle cx="12" cy="12" r="9" />
          <path d="M9.5 9.5a2.5 2.5 0 1 1 3.7 2.2c-.8.5-1.2 1-1.2 2" />
          <circle cx="12" cy="17" r="0.15" fill="currentColor" stroke="currentColor" strokeWidth="1.4" />
        </g>
      );
  }
}

/** Icon-first visual for one item id. Renders the empty-slot ghost glyph for
 *  "minecraft:air" / unset, and the unknown "?" glyph for an id that isn't in
 *  the catalog at all (should not normally happen — every id offered by the
 *  picker comes from MINECRAFT_ITEMS). */
export function ItemIcon({ itemId, className }: { itemId: string | undefined | null; className?: string }) {
  if (!itemId) {
    return (
      <svg viewBox="0 0 24 24" className={className ?? "h-6 w-6"} style={{ color: "#475569" }} aria-hidden="true">
        <Glyph glyph="air" />
      </svg>
    );
  }
  const item = MINECRAFT_ITEMS_BY_ID.get(itemId);
  if (!item) {
    return (
      <svg viewBox="0 0 24 24" className={className ?? "h-6 w-6"} style={{ color: "#475569" }} aria-hidden="true">
        <Glyph glyph="unknown" />
      </svg>
    );
  }
  const glyph = resolveGlyph(item);
  const color = resolveColor(item);
  return (
    <svg viewBox="0 0 24 24" className={className ?? "h-6 w-6"} style={{ color }} aria-hidden="true">
      <Glyph glyph={glyph} />
    </svg>
  );
}

/** Small colored dot used in category filter chips — same tint an item of
 *  that category would resolve to by default. */
export function CategorySwatch({ category, className }: { category: string; className?: string }) {
  const color = DEFAULT_CATEGORY_COLOR[category] ?? "#94a3b8";
  return <span className={className ?? "h-2 w-2 rounded-full"} style={{ backgroundColor: color }} aria-hidden="true" />;
}

"use client";

/**
 * Player-inventory editor for the free Minecraft Players tab.
 *
 * READ THIS BEFORE CHANGING THE COPY: vanilla RCON has no "read a player's
 * inventory" command — the only primitive is a write-only
 * `/item replace entity <player> <slot> with <item>[<count>]`. This UI is
 * deliberately NOT a live view of what's in someone's inventory; it's a
 * "set this slot to become X" tool. Every slot control below starts blank/
 * unselected on every render — it never claims to reflect current contents.
 *
 * UI NOTE: slots render as icon tiles (see ItemIcon.tsx for where those
 * icons come from and why — short version: hand-authored original SVG
 * glyphs, not Minecraft textures, because a properly-licensed source of
 * real item renders wasn't available for commercial use — see that file's
 * header for the full explanation). Clicking a tile opens a searchable
 * icon-grid picker instead of a 392-row text dropdown.
 */
import { useEffect, useMemo, useState, useTransition } from "react";
import { getFreeMinecraftPlayers } from "@/lib/actions-free-minecraft";
import { applyPlayerInventoryEdit, type ApplyInventoryEditState } from "@/lib/actions-freemc-inventory";
import { MINECRAFT_ITEMS, MINECRAFT_ITEM_CATEGORIES, type MinecraftItem } from "@/lib/minecraft-items";
import { ARMOR_SLOTS, HAND_SLOTS, HOTBAR_SLOTS, MAIN_INVENTORY_SLOTS, type SlotDef } from "@/lib/minecraft-slots";
import { ItemIcon, CategorySwatch } from "./ItemIcon";

type PendingEdit = { itemId: string; count: number };

const CLEAR_ID = "minecraft:air";

export function InventoryEditor({ running }: { running: boolean }) {
  const [players, setPlayers] = useState<{ name: string }[] | null>(null);
  const [playersError, setPlayersError] = useState<string | null>(null);
  const [player, setPlayer] = useState<string>("");
  const [edits, setEdits] = useState<Record<string, PendingEdit>>({});
  const [result, setResult] = useState<ApplyInventoryEditState | null>(null);
  const [pending, startTransition] = useTransition();
  const [refreshing, startRefresh] = useTransition();
  const [pickerSlot, setPickerSlot] = useState<SlotDef | null>(null);

  function refreshPlayers() {
    startRefresh(async () => {
      const res = await getFreeMinecraftPlayers();
      if (res.ok) {
        setPlayers(res.players);
        setPlayersError(null);
        if (!res.players.some((p) => p.name === player)) setPlayer(res.players[0]?.name ?? "");
      } else {
        setPlayersError(res.error);
        setPlayers(null);
      }
    });
  }
  useEffect(() => {
    if (running) refreshPlayers();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [running]);

  function setSlot(slot: string, next: Partial<PendingEdit>) {
    setEdits((prev) => {
      const current = prev[slot] ?? { itemId: "", count: 1 };
      const merged = { ...current, ...next };
      // Dropping back to "no item chosen" removes the pending edit entirely
      // rather than submitting a no-op.
      if (!merged.itemId) {
        const { [slot]: _drop, ...rest } = prev;
        return rest;
      }
      return { ...prev, [slot]: merged };
    });
  }

  const pendingCount = Object.keys(edits).length;

  function submit() {
    if (!player || pendingCount === 0) return;
    const payload = Object.entries(edits).map(([slot, e]) => ({
      slot,
      itemId: e.itemId,
      count: e.itemId === CLEAR_ID ? 1 : e.count,
    }));
    const fd = new FormData();
    fd.set("player", player);
    fd.set("edits", JSON.stringify(payload));
    startTransition(async () => {
      const res = await applyPlayerInventoryEdit({}, fd);
      setResult(res);
      if (!res.error) setEdits({});
    });
  }

  return (
    <div className="card space-y-5">
      <div>
        <h3 className="font-semibold text-[var(--fg)]">Give items</h3>
        <p className="mt-1 text-sm text-slate-400">
          Minecraft doesn&apos;t let us read what&apos;s currently in a player&apos;s inventory over RCON — this tool only
          <span className="text-slate-300"> sets</span> slots to whatever you pick below. It doesn&apos;t show current
          contents, and picking a slot below will overwrite whatever&apos;s already there.
        </p>
      </div>

      {!running ? (
        <p className="text-sm text-slate-500">Server is asleep — nobody&apos;s connected. Wake it up to edit inventories.</p>
      ) : (
        <>
          <div className="flex flex-wrap items-end gap-3">
            <div>
              <label className="label mb-1 block">Player</label>
              <select className="input" value={player} onChange={(e) => setPlayer(e.target.value)} disabled={!players?.length}>
                {!players?.length && <option value="">No one online</option>}
                {players?.map((p) => (
                  <option key={p.name} value={p.name}>
                    {p.name}
                  </option>
                ))}
              </select>
            </div>
            <button type="button" className="btn-ghost text-xs" onClick={refreshPlayers} disabled={refreshing}>
              {refreshing ? "Refreshing…" : "Refresh players"}
            </button>
            {playersError && <p className="text-sm text-red-400">{playersError}</p>}
          </div>

          {player && (
            <>
              <div className="rounded-2xl border border-white/[0.06] bg-black/20 p-4">
                <div className="flex flex-wrap items-start gap-6">
                  <SlotGroup title="Armor" slots={ARMOR_SLOTS} edits={edits} onOpen={setPickerSlot} tileSize="h-14 w-14" />
                  <SlotGroup title="Hands" slots={HAND_SLOTS} edits={edits} onOpen={setPickerSlot} tileSize="h-14 w-14" />
                </div>

                <div className="mt-5">
                  <h4 className="text-xs font-semibold uppercase tracking-wide text-slate-500">Main inventory</h4>
                  <div className="mt-2 grid w-fit grid-cols-9 gap-1.5">
                    {MAIN_INVENTORY_SLOTS.map((s) => (
                      <SlotTile key={s.slot} slotDef={s} value={edits[s.slot]} onOpen={() => setPickerSlot(s)} size="h-11 w-11" />
                    ))}
                  </div>
                </div>

                <div className="mt-4 border-t border-white/[0.06] pt-4">
                  <h4 className="text-xs font-semibold uppercase tracking-wide text-brand-300">Hotbar</h4>
                  <div className="mt-2 grid w-fit grid-cols-9 gap-1.5 rounded-xl border border-brand-500/20 bg-brand-500/[0.06] p-1.5">
                    {HOTBAR_SLOTS.map((s) => (
                      <SlotTile key={s.slot} slotDef={s} value={edits[s.slot]} onOpen={() => setPickerSlot(s)} size="h-11 w-11" />
                    ))}
                  </div>
                </div>
              </div>

              {result?.error && (
                <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{result.error}</div>
              )}
              {result?.results && (
                <div className="rounded-lg border border-white/[0.08] bg-black/20 p-3 text-xs">
                  {result.results.map((r) => (
                    <p key={r.slot} className={r.ok ? "text-emerald-300" : "text-red-400"}>
                      {r.slot}: {r.ok ? "applied" : r.message}
                    </p>
                  ))}
                </div>
              )}

              <div className="flex items-center justify-between border-t border-white/[0.06] pt-4">
                <p className="text-xs text-slate-500">
                  {pendingCount === 0 ? "Click a slot above to pick an item." : `${pendingCount} slot${pendingCount === 1 ? "" : "s"} queued to change.`}
                </p>
                <button type="button" className="btn-primary text-sm" onClick={submit} disabled={pending || pendingCount === 0}>
                  {pending ? "Applying…" : "Apply to " + player}
                </button>
              </div>
            </>
          )}
        </>
      )}

      {pickerSlot && (
        <ItemPickerModal
          slotDef={pickerSlot}
          current={edits[pickerSlot.slot]}
          onClose={() => setPickerSlot(null)}
          onPick={(itemId, count) => {
            setSlot(pickerSlot.slot, { itemId, count });
            setPickerSlot(null);
          }}
        />
      )}
    </div>
  );
}

function SlotGroup({
  title,
  slots,
  edits,
  onOpen,
  tileSize,
}: {
  title: string;
  slots: SlotDef[];
  edits: Record<string, PendingEdit>;
  onOpen: (slot: SlotDef) => void;
  tileSize: string;
}) {
  return (
    <div>
      <h4 className="text-xs font-semibold uppercase tracking-wide text-slate-500">{title}</h4>
      <div className="mt-2 flex gap-1.5">
        {slots.map((s) => (
          <SlotTile key={s.slot} slotDef={s} value={edits[s.slot]} onOpen={() => onOpen(s)} size={tileSize} />
        ))}
      </div>
    </div>
  );
}

/** One icon-first inventory tile: shows the pending item's glyph + a count
 *  badge, and opens the picker on click. Always starts empty on render —
 *  see the file header on why this must never look like it's showing
 *  current server-side contents. */
function SlotTile({
  slotDef,
  value,
  onOpen,
  size,
}: {
  slotDef: SlotDef;
  value: PendingEdit | undefined;
  onOpen: () => void;
  size: string;
}) {
  const active = !!value?.itemId;
  const isClear = value?.itemId === CLEAR_ID;
  const item = active ? MINECRAFT_ITEMS.find((it) => it.id === value!.itemId) : undefined;
  return (
    <button
      type="button"
      onClick={onOpen}
      title={item ? `${slotDef.label}: ${item.label}` : slotDef.label}
      className={`relative ${size} shrink-0 rounded-lg border transition-colors ${
        active
          ? isClear
            ? "border-slate-500/40 bg-slate-500/10"
            : "border-brand-400/50 bg-brand-500/10 hover:bg-brand-500/15"
          : "border-white/[0.08] bg-navy-900/60 hover:border-white/20 hover:bg-navy-800/60"
      }`}
    >
      <span className="flex h-full w-full items-center justify-center">
        <ItemIcon itemId={value?.itemId} className="h-6 w-6" />
      </span>
      {active && !isClear && (value?.count ?? 1) > 1 && (
        <span className="absolute bottom-0.5 right-1 rounded bg-navy-950/90 px-1 text-[9px] font-bold leading-tight text-slate-100">
          {value?.count}
        </span>
      )}
    </button>
  );
}

/** Searchable icon-grid picker for one slot. Filters the ~400-item catalog
 *  by free-text query and/or category chip — the same catalog + categories
 *  lib/minecraft-items.ts already exposes, just rendered as icons instead of
 *  392 text rows. */
function ItemPickerModal({
  slotDef,
  current,
  onClose,
  onPick,
}: {
  slotDef: SlotDef;
  current: PendingEdit | undefined;
  onClose: () => void;
  onPick: (itemId: string, count: number) => void;
}) {
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState<string>("All");
  const [count, setCount] = useState(current?.count ?? 1);

  const matches = useMemo(() => {
    const q = query.trim().toLowerCase();
    return MINECRAFT_ITEMS.filter((it) => {
      if (category !== "All" && it.category !== category) return false;
      if (it.id === CLEAR_ID) return false; // clearing has its own dedicated button
      if (!q) return true;
      return it.label.toLowerCase().includes(q) || it.id.includes(q);
    }).slice(0, 120);
  }, [query, category]);

  function pick(it: MinecraftItem) {
    onPick(it.id, it.id === CLEAR_ID ? 1 : Math.max(1, Math.min(64, count || 1)));
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4" role="dialog" aria-modal="true" aria-label={`Choose item for ${slotDef.label}`}>
      <div className="absolute inset-0 bg-navy-950/70 backdrop-blur-sm" onClick={onClose} />
      <div className="relative flex max-h-[85vh] w-full max-w-2xl flex-col overflow-hidden rounded-2xl border border-white/[0.08] bg-navy-900/95 shadow-[0_24px_80px_-24px_rgb(0_0_0_/_0.8)] backdrop-blur-xl">
        <div className="flex items-center justify-between border-b border-white/[0.06] px-5 py-4">
          <div>
            <p className="text-xs uppercase tracking-wide text-slate-500">Set slot</p>
            <h3 className="font-semibold text-[var(--fg)]">{slotDef.label}</h3>
          </div>
          <button type="button" className="btn-ghost text-xs" onClick={onClose}>
            Close
          </button>
        </div>

        <div className="space-y-3 border-b border-white/[0.06] px-5 py-3">
          <div className="flex flex-wrap items-center gap-2">
            <input
              autoFocus
              className="input flex-1"
              placeholder="Search items…"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
            />
            <div className="flex items-center gap-1.5">
              <label className="label" htmlFor="picker-count">
                Count
              </label>
              <input
                id="picker-count"
                type="number"
                className="input w-16 px-2 py-1.5 text-sm"
                min={1}
                max={64}
                value={count}
                onChange={(e) => setCount(Math.max(1, Math.min(64, Number(e.target.value) || 1)))}
              />
            </div>
          </div>
          <div className="flex flex-wrap gap-1.5">
            <CategoryChip label="All" active={category === "All"} onClick={() => setCategory("All")} />
            {MINECRAFT_ITEM_CATEGORIES.filter((c) => c !== "Utility" || true).map((c) => (
              <CategoryChip key={c} label={c} active={category === c} onClick={() => setCategory(c)} />
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4">
          <button
            type="button"
            onClick={() => pick(MINECRAFT_ITEMS.find((it) => it.id === CLEAR_ID)!)}
            className="mb-3 flex w-full items-center gap-2 rounded-lg border border-white/[0.08] bg-black/20 px-3 py-2 text-left text-xs text-slate-400 hover:border-white/20 hover:bg-black/30"
          >
            <ItemIcon itemId={undefined} className="h-4 w-4" />
            Clear slot (set to empty / air)
          </button>

          {matches.length === 0 ? (
            <p className="px-1 py-6 text-center text-sm text-slate-500">No items match &quot;{query}&quot;.</p>
          ) : (
            <div className="grid grid-cols-4 gap-2 sm:grid-cols-6 md:grid-cols-8">
              {matches.map((it) => (
                <button
                  key={it.id}
                  type="button"
                  onClick={() => pick(it)}
                  title={it.label}
                  className="flex flex-col items-center gap-1 rounded-lg border border-white/[0.06] bg-navy-900/60 p-2 text-center transition-colors hover:border-brand-400/50 hover:bg-brand-500/10"
                >
                  <ItemIcon itemId={it.id} className="h-7 w-7" />
                  <span className="line-clamp-2 text-[10px] leading-tight text-slate-400">{it.label}</span>
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function CategoryChip({ label, active, onClick }: { label: string; active: boolean; onClick: () => void }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-medium transition-colors ${
        active ? "border-brand-400/50 bg-brand-500/15 text-brand-200" : "border-white/[0.08] text-slate-400 hover:border-white/20 hover:text-slate-200"
      }`}
    >
      {label !== "All" && <CategorySwatch category={label} />}
      {label}
    </button>
  );
}

