213	function ItemPicker({ value, onSelect }: { value: string; onSelect: (itemId: string) => void }) {
214	  const [query, setQuery] = useState("");
215	  const [open, setOpen] = useState(false);
216	  const selected = MINECRAFT_ITEMS.find((it) => it.id === value);
217	
218	  const matches = useMemo(() => {
219	    if (!query.trim()) return MINECRAFT_ITEMS.slice(0, 40);
220	    const q = query.trim().toLowerCase();
221	    return MINECRAFT_ITEMS.filter((it) => it.label.toLowerCase().includes(q) || it.id.includes(q)).slice(0, 40);
222	  }, [query]);
223	
224	  return (
225	    <div className="relative">
226	      <input
227	        className="input w-full px-1.5 py-1 text-xs"
228	        placeholder={selected ? selected.label : "Search item…"}
