230	        onFocus={() => setOpen(true)}
231	        onChange={(e) => {
232	          setQuery(e.target.value);
233	          setOpen(true);
234	        }}
235	        onBlur={() => setTimeout(() => setOpen(false), 150)}
236	      />
237	      {selected && !open && <p className="mt-0.5 truncate text-[11px] text-brand-300">{selected.label}</p>}
238	      {open && (
239	        <div className="absolute z-10 mt-1 max-h-56 w-56 overflow-y-auto rounded-lg border border-white/10 bg-navy-900 shadow-xl">
240	          <button
241	            type="button"
242	            className="block w-full px-2 py-1.5 text-left text-[11px] text-slate-500 hover:bg-white/5"
243	            onMouseDown={(e) => {
244	              e.preventDefault();
245	              onSelect("");
246	              setQuery("");
247	              setOpen(false);
248	            }}
249	          >
250	            Clear selection
251	          </button>
252	          {matches.map((it: MinecraftItem) => (
253	            <button
254	              key={it.id}
255	              type="button"
256	              className="block w-full px-2 py-1.5 text-left text-[11px] hover:bg-white/5"
257	              onMouseDown={(e) => {
258	                e.preventDefault();
259	                onSelect(it.id);
260	                setQuery("");
261	                setOpen(false);
262	              }}
263	            >
264	              <span className="text-[var(--fg)]">{it.label}</span>
265	              <span className="ml-1 text-slate-500">{it.category}</span>
266	            </button>
267	          ))}
268	          {matches.length === 0 && <p className="px-2 py-1.5 text-[11px] text-slate-500">No matches.</p>}
269	        </div>
270	      )}
271	    </div>
272	  );
273	}
